{"path": "forth.py", "content": "class StackUnderflowError(Exception):
    """Exception raised when the stack has too few items for an operation.

    message: explanation of the error.
    """

    def __init__(self, message):
        super().__init__(message)
        self.message = message


def _is_number(token):
    digits = token[1:] if token.startswith('-') else token
    return digits.isdigit() and digits.isascii()


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError('Insufficient number of items in stack')
    values = stack[-count:]
    del stack[-count:]
    return values


def _add(stack):
    a, b = _pop(stack, 2)
    stack.append(a + b)


def _sub(stack):
    a, b = _pop(stack, 2)
    stack.append(a - b)


def _mul(stack):
    a, b = _pop(stack, 2)
    stack.append(a * b)


def _div(stack):
    a, b = _pop(stack, 2)
    if b == 0:
        raise ZeroDivisionError('divide by zero')
    quotient = abs(a) // abs(b)
    stack.append(quotient if (a < 0) == (b < 0) else -quotient)


def _dup(stack):
    (a,) = _pop(stack, 1)
    stack.extend([a, a])


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    a, b = _pop(stack, 2)
    stack.extend([b, a])


def _over(stack):
    a, b = _pop(stack, 2)
    stack.extend([a, b, a])


_BUILTINS = {
    '+': _add,
    '-': _sub,
    '*': _mul,
    '/': _div,
    'dup': _dup,
    'drop': _drop,
    'swap': _swap,
    'over': _over,
}


def _expand(tokens, words):
    """Resolve tokens into a flat list of ints and builtin callables,
    using the word definitions as they exist right now."""
    result = []
    for token in tokens:
        if token in words:
            result.extend(words[token])
        elif _is_number(token):
            result.append(int(token))
        elif token in _BUILTINS:
            result.append(_BUILTINS[token])
        else:
            raise ValueError('undefined operation')
    return result


def evaluate(input_data):
    words = {}
    stack = []
    tokens = ' '.join(input_data).lower().split()
    index = 0
    while index < len(tokens):
        token = tokens[index]
        if token == ':':
            try:
                end = tokens.index(';', index)
            except ValueError:
                raise ValueError('undefined operation') from None
            if end - index < 2:
                raise ValueError('undefined operation')
            name = tokens[index + 1]
            if _is_number(name):
                raise ValueError('illegal operation')
            words[name] = _expand(tokens[index + 2:end], words)
            index = end + 1
            continue
        for item in _expand([token], words):
            if callable(item):
                item(stack)
            else:
                stack.append(item)
        index += 1
    return stack
